//! Table tests of a type variable name whose text is longer than 255 bytes, inside a transaction
//! that has an id: the tree that holds the name arrives as BYTES. sigmastate's type writer throws
//! for such a name (v6.0.6 `TypeSerializer.scala:122-126`), so every WRITE of the tree fails and
//! nothing else does:
//! - a box read by `Global.deserializeTo[Box]` keeps the bytes it was read from (`ErgoBox.scala:87-89`):
//!   its `id`, `bytes`, `propositionBytes` and `==` are over those; `bytesWithoutRef`
//!   (`ErgoBoxCandidate.scala:54`) and `Global.serialize` (`DataSerializer.scala:16-18`) write it;
//! - `substConstants` writes every constant again and copies the body
//!   (`ErgoTreeSerializer.scala:320-378`).
//!
//! The rows are sigma-state 6.0.7's at activated version 3 (the round's `measure/rows/eval.txt`,
//! `out/eval-jvm.txt`; generated by `measure/tests/gen_tests.py`), for three names: `ff85` (85
//! malformed bytes, a text of 255 bytes: written), `mix256` (a text of 256) and `ff86` (258).
use crate::eval::test_util::{eval_body, jvm_text};
use ergotree_ir::ergo_tree::ErgoTreeVersion;
use ergotree_ir::mir::value::Value;

/// A row: its name in the round's row set, the expression's bytes, the tree version, the value as
/// [`text`] prints it, `REFUSED` for the type writer's refusal or `ERR` for any other failure, and
/// the cost counter. Where `Global.serialize` refuses a box for its tree, the box's value has
/// been written and charged (v6.0.6 `ErgoBoxCandidate.scala:141-142`)
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// A value as `jvm_text` prints it; of a collection the first 100 items, which is what the jars'
/// probe prints
fn text(v: &Value<'_>) -> alloc::string::String {
    match v {
        Value::Coll(c) if c.len() > 100 => {
            let items: alloc::vec::Vec<_> = c.as_vec().iter().take(100).map(jvm_text).collect();
            alloc::format!("Coll({})", items.join(","))
        }
        v => jvm_text(v),
    }
}

/// The rows whose outcome, value or cost counter is not the table's
fn wrong_rows(rows: &[Row]) -> alloc::vec::Vec<alloc::string::String> {
    let mut wrong = alloc::vec::Vec::new();
    for (name, body, version, expected, cost) in rows {
        let (res, stopped_at) = eval_body(body, ErgoTreeVersion::from(*version));
        let got = match &res {
            Ok(v) => text(v),
            // the refusal reaches the evaluator as the writer's error or, through
            // `substConstants`, as text: its message is the same
            Err(e) if alloc::format!("{e:?}").contains("out of unsigned byte range") => {
                "REFUSED".into()
            }
            Err(_) => "ERR".into(),
        };
        if got != *expected || *cost != stopped_at {
            wrong.push(alloc::format!(
                "{name}: expected {expected} at {cost}, got {got} at {stopped_at}"
            ));
        }
    }
    wrong
}

