#[test]
fn a_box_with_a_name_its_writer_refuses_is_read_and_not_written() {
    assert_eq!(BOXES.len(), 66);
    let wrong = wrong_rows(BOXES);
    assert!(
        wrong.is_empty(),
        "{} rows:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
}

#[test]
fn subst_constants_refuses_a_constant_whose_type_holds_such_a_name() {
    assert_eq!(SUBST_CONSTANTS.len(), 30);
    let wrong = wrong_rows(SUBST_CONSTANTS);
    assert!(
        wrong.is_empty(),
        "{} rows:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
}
